    AND m.code = 'limitation_of_liability'
    AND ct.code = 'limitation_of_liability_exceptions_fraud_willful_indemnification_confidentiality_ip';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



