  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'limitation_of_liability'
    AND ct.code = 'limitation_mutual_vs_one_sided_application';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- termination_and_remedies / amazon_termination_for_convenience (20 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'termination_and_remedies'
    AND ct.code = 'amazon_termination_for_convenience';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- termination_and_remedies / amazon_termination_for_cause_prodco_breach (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'termination_and_remedies'
