    ON CONFLICT DO NOTHING;
  END IF;



  -- termination_and_remedies / termination_consequences_rights_reversion_payment (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'termination_and_remedies'
    AND ct.code = 'termination_consequences_rights_reversion_payment';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- termination_and_remedies / suspension_rights_pending_cure_or_investigation (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
