    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The limitations of liability set forth in this Section shall not apply to ProdCo. ProdCo''s liability to Amazon and the Amazon Indemnitees under this Agreement, including under the indemnification provisions, shall be unlimited.', ARRAY['limitations of liability','not apply','ProdCo','ProdCo''s liability','Amazon','Amazon Indemnitees','Agreement','including','indemnification','unlimited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo excluded from limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo exclusion from liability limitations is essential for Amazon protection. ProdCo''s content obligations create risks that must not be capped."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding any other provision of this Agreement, ProdCo''s liability under the indemnification provisions, for breach of representations and warranties, and for breach of confidentiality obligations shall not be subject to any limitation or cap.', ARRAY['notwithstanding','ProdCo''s liability','indemnification','breach','representations','warranties','breach','confidentiality','not subject to','limitation','cap']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Specific ProdCo obligation carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carves out key ProdCo obligations (indemnification, reps/warranties, confidentiality) from any limitations. Core protection areas must be unlimited."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees that no limitation of liability, whether contained in this Agreement or implied by law, shall apply to: (a) ProdCo''s indemnification obligations; (b) breach of ProdCo''s representations and warranties; (c) ProdCo''s confidentiality obligations; (d) infringement or misappropriation of intellectual property; or (e) ProdCo''s fraud, gross negligence or willful misconduct.', ARRAY['no limitation','liability','apply','ProdCo''s indemnification','breach','representations','warranties','confidentiality','infringement','misappropriation','intellectual property','fraud','gross negligence','willful misconduct']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Comprehensive ProdCo carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of ProdCo obligations excluded from limitations. IP infringement and fraud/willful misconduct explicitly carved out."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that Amazon is relying on the unlimited nature of ProdCo''s indemnification and warranty obligations in entering into this Agreement, and that any limitation on such obligations would be material to Amazon''s willingness to contract.', ARRAY['acknowledges','agrees','Amazon relying','unlimited nature','ProdCo''s indemnification','warranty obligations','entering into','Agreement','limitation','material','Amazon''s willingness','contract']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo acknowledgment of unlimited liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment reinforces that unlimited liability is bargained-for and essential to the deal, preventing later challenges."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any liability cap or limitation that might otherwise apply under this Agreement or applicable law is expressly waived by ProdCo with respect to claims arising from: the Program content; ProdCo''s production activities; and ProdCo''s personnel.', ARRAY['liability cap','limitation','otherwise apply','Agreement','applicable law','expressly waived','ProdCo','claims','Program content','production activities','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Waiver of content/production limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Express waiver of limitations for content, production, and personnel claims. Addresses potential statutory limitations in some jurisdictions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The consequential damages exclusion set forth above is mutual; however, such exclusion shall not limit ProdCo''s indemnification obligations, which shall include all damages (including consequential damages) incurred by Amazon Indemnitees from third-party claims.', ARRAY['consequential damages exclusion','mutual','not limit','ProdCo''s indemnification','include','all damages','including consequential','Amazon Indemnitees','third-party claims']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Indemnification preserved from mutual exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that mutual consequential damages exclusion doesn''t affect ProdCo''s indemnification, which must cover all third-party damages including consequential."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For the avoidance of doubt, ProdCo''s liability under this Agreement is not capped, limited, or otherwise restricted. ProdCo shall be fully liable for all damages, losses, costs and expenses arising from breach of this Agreement or from any matter subject to indemnification.', ARRAY['avoidance of doubt','ProdCo''s liability','not capped','limited','restricted','fully liable','all damages','losses','costs','expenses','breach','Agreement','indemnification']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Explicit unlimited ProdCo liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit statement of unlimited ProdCo liability prevents any ambiguity. Comprehensive coverage of all damage types."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is unlimited for indemnification, reps/warranties, and confidentiality. For other ProdCo obligations (such as delivery schedules and format requirements), ProdCo''s liability shall be capped at the Production Fee.', ARRAY['ProdCo''s liability','unlimited','indemnification','reps/warranties','confidentiality','other obligations','delivery schedules','format requirements','capped','Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Limited cap for operational obligations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cap for purely operational obligations (delivery, format) while preserving unlimited liability for core content/indemnification may be acceptable. Legal should confirm scope of ''operational'' is narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is unlimited. However, ProdCo shall not be liable for consequential damages to Amazon arising from ProdCo''s breach of purely administrative obligations (e.g., late delivery of accounting statements), provided such exclusion shall not apply to the indemnification or content-related obligations.', ARRAY['ProdCo''s liability','unlimited','not liable','consequential damages','Amazon','breach','administrative obligations','late delivery','accounting','exclusion','not apply','indemnification','content-related']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Administrative consequential carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Narrow carveout for consequential damages from administrative breaches may be acceptable if truly limited to administrative matters and doesn''t affect content/indemnification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is not capped for core obligations. Both parties acknowledge that ProdCo maintains errors and omissions insurance with coverage of at least $5,000,000, which provides financial backing for ProdCo''s unlimited liability obligations.', ARRAY['ProdCo''s liability','not capped','core obligations','acknowledge','E&O insurance','coverage','$5,000,000','financial backing','unlimited liability']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Insurance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Insurance acknowledgment provides context for unlimited liability. Doesn''t limit liability but confirms financial backing exists. Beneficial addition."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is unlimited. In the event of a claim exceeding $[threshold], ProdCo shall have the right to dispute the amount, and the parties shall engage in good faith discussions before Amazon may pursue recovery beyond such threshold.', ARRAY['ProdCo''s liability','unlimited','claim exceeding','threshold','right to dispute','amount','good faith discussions','Amazon may pursue','recovery','beyond threshold']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Dispute process for large claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith discussion requirement for large claims doesn''t limit liability but provides process. May be acceptable if it doesn''t create precondition to recovery."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification liability is unlimited. ProdCo''s liability for direct breaches by ProdCo of its non-indemnification obligations (e.g., service delivery) shall be subject to a cap equal to the Production Fee.', ARRAY['ProdCo''s indemnification','liability','unlimited','ProdCo''s liability','direct breaches','non-indemnification obligations','service delivery','subject to','cap','Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Cap for non-indemnification direct breaches", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Preserving unlimited indemnification while capping service delivery breaches may be acceptable. Legal should confirm that content-related claims flow through indemnification, not direct breach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability under the indemnification provisions is unlimited. ProdCo shall maintain insurance with Amazon named as additional insured, with coverage of not less than [amount] per occurrence and [amount] aggregate, to support these unlimited obligations.', ARRAY['ProdCo''s liability','indemnification','unlimited','maintain insurance','Amazon','additional insured','coverage','per occurrence','aggregate','support','unlimited obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Insurance requirements for unlimited liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Insurance requirement as support for unlimited liability is beneficial. Doesn''t cap liability but ensures financial backing for indemnification obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s aggregate liability under this Agreement, including under the indemnification provisions, shall not exceed the Production Fee paid to ProdCo hereunder.', ARRAY['ProdCo''s aggregate liability','Agreement','including','indemnification','not exceed','Production Fee','paid']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "ProdCo cap including indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping ProdCo''s liability including indemnification would massively limit Amazon''s recovery for content claims. ProdCo''s content liability must be unlimited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The liability limitations in this Section apply equally to both parties. Each party''s aggregate liability shall be capped at the Production Fee, with no party having greater or lesser liability exposure than the other.', ARRAY['liability limitations','apply equally','both parties','each party''s','aggregate liability','capped','Production Fee','no party','greater','lesser','liability exposure']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced mutual liability caps", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced mutual caps ignore fundamental asymmetry. ProdCo creates content that generates claims; Amazon doesn''t. Mutual caps would gut Amazon''s protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s liability for indemnification claims shall be limited to the extent of available insurance coverage. Claims exceeding insurance coverage shall not be ProdCo''s responsibility.', ARRAY['ProdCo''s liability','indemnification','limited','extent','available insurance coverage','claims exceeding','insurance','not','ProdCo''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Insurance-limited liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting ProdCo liability to insurance coverage shifts excess risk to Amazon. ProdCo must be liable regardless of insurance limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not be liable for consequential, indirect, special, incidental or punitive damages to Amazon under any circumstances, including in connection with indemnification claims.', ARRAY['ProdCo','not liable','consequential','indirect','special','incidental','punitive damages','Amazon','any circumstances','including','indemnification claims']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "ProdCo consequential exclusion including indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo consequential damages exclusion covering indemnification would exclude vast categories of third-party claim damages. ProdCo must cover all indemnified damages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s liability is unlimited for willful misconduct and fraud only. For all other breaches, including breach of representations and warranties, ProdCo''s liability shall be capped at two times (2x) the Production Fee.', ARRAY['ProdCo''s liability','unlimited','willful misconduct','fraud only','other breaches','including','representations','warranties','capped','2x','Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Cap on rep/warranty breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping rep/warranty breach liability would limit recovery for core content claims (infringement, defamation). Rep/warranty breaches must be unlimited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification liability is unlimited. However, ProdCo''s liability shall be reduced proportionately to the extent Amazon contributed to the claim through Amazon''s approvals, direction, or creative input.', ARRAY['ProdCo''s indemnification','unlimited','liability','reduced proportionately','extent','Amazon contributed','claim','Amazon''s approvals','direction','creative input']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Proportionate reduction for Amazon contribution", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Proportionate reduction for Amazon approvals/direction would reduce ProdCo liability for virtually all claims since Amazon provides creative input. Content responsibility is ProdCo''s regardless."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The limitations of liability set forth in this Section shall not apply to: (a) a party''s indemnification obligations; (b) a party''s breach of confidentiality obligations; (c) infringement or misappropriation of intellectual property; (d) fraud or intentional misconduct; or (e) obligations that by their nature cannot be limited (such as payment obligations).', ARRAY['limitations of liability','not apply','indemnification obligations','breach','confidentiality','infringement','misappropriation','intellectual property','fraud','intentional misconduct','obligations','cannot be limited','payment obligations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard super-cap exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive exceptions covering indemnification, confidentiality, IP, fraud/misconduct, and inherently unlimited obligations. Essential carveouts from any caps."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding any limitation herein, neither party''s liability shall be limited with respect to: (i) death or personal injury caused by negligence; (ii) fraud or fraudulent misrepresentation; (iii) willful misconduct or gross negligence; (iv) indemnification obligations; or (v) breach of confidentiality or data protection obligations.', ARRAY['notwithstanding','limitation','neither party''s liability','limited','death','personal injury','negligence','fraud','fraudulent misrepresentation','willful misconduct','gross negligence','indemnification','confidentiality','data protection']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Personal injury and data protection exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes death/personal injury and data protection in exceptions. Important for production safety and modern data handling requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The following shall not be subject to any cap, exclusion, or limitation of liability: ProdCo''s indemnification obligations; ProdCo''s representations and warranties; ProdCo''s confidentiality obligations; and any claim arising from ProdCo''s fraud, willful misconduct, or gross negligence.', ARRAY['not subject to','cap','exclusion','limitation','ProdCo''s indemnification','representations','warranties','confidentiality','claim','ProdCo''s fraud','willful misconduct','gross negligence']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo-specific unlimited categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo-specific carveouts ensuring all core content and conduct obligations are unlimited. Includes reps/warranties as separate category."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Exclusions from the liability limitations include: (a) any amounts owed under indemnification provisions (which shall cover all damages including consequential damages); (b) breach of any obligation to maintain confidentiality of the other party''s information; (c) infringement, misappropriation, or unauthorized use of intellectual property rights.', ARRAY['Exclusions','liability limitations','amounts owed','indemnification','all damages','consequential','breach','confidentiality','other party''s information','infringement','misappropriation','unauthorized use','intellectual property']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Indemnification covers all damages clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that indemnification exception includes all damages (including consequential). Important to ensure limitation doesn''t indirectly cap indemnification."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Neither the liability cap nor the consequential damages exclusion shall apply to: fraud; willful misconduct; gross negligence; indemnification obligations; confidentiality breaches; intellectual property infringement; or violations of law resulting in fines or penalties.', ARRAY['liability cap','consequential damages exclusion','not apply','fraud','willful misconduct','gross negligence','indemnification','confidentiality','intellectual property infringement','violations of law','fines','penalties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Legal violation fines/penalties exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes legal violation fines/penalties in exceptions. Important for regulatory compliance matters where penalties may be substantial."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The parties agree that the exceptions to liability limitations set forth herein are essential to the Agreement and are not subject to negotiation or modification. Any provision purporting to limit these exceptions shall be void and of no effect.', ARRAY['exceptions','liability limitations','essential','Agreement','not subject to','negotiation','modification','provision','limit','exceptions','void','no effect']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Non-waivable exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protective language preventing future modification of exceptions. Ensures exceptions remain in place even if Agreement is amended."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For the avoidance of doubt, the limitations set forth in this Section shall not limit any party''s liability for: (i) breach of exclusivity obligations; (ii) unauthorized use or disclosure of the other party''s intellectual property or confidential information; (iii) failure to comply with data protection laws; or (iv) any obligation that cannot lawfully be limited.', ARRAY['avoidance of doubt','limitations','not limit','liability','breach','exclusivity','unauthorized use','disclosure','intellectual property','confidential information','data protection laws','cannot lawfully be limited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Exclusivity and data protection exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes exclusivity breach and data protection in exceptions. Addresses modern privacy requirements and relationship exclusivity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exceptions to limitations include fraud, willful misconduct, and indemnification. For gross negligence, the liability cap shall be increased to two times (2x) the standard cap, but gross negligence shall not be entirely unlimited.', ARRAY['Exceptions','limitations','fraud','willful misconduct','indemnification','gross negligence','liability cap','increased','2x','standard cap','not entirely unlimited']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Elevated cap for gross negligence", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Elevated (but not unlimited) cap for gross negligence may be acceptable as middle ground. Legal should confirm fraud and willful misconduct remain unlimited."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Standard exceptions apply to limitations. With respect to confidentiality breaches, the exception applies only to breaches involving intentional disclosure to competitors or public disclosure of NPI, not to inadvertent disclosures to non-competitors.', ARRAY['Standard exceptions','limitations','confidentiality breaches','exception applies','only','intentional disclosure','competitors','public disclosure','NPI','not','inadvertent','non-competitors']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Limited confidentiality exception scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting confidentiality exception to intentional/competitor/public disclosures narrows scope but covers most serious scenarios. Legal should assess if inadvertent disclosure exclusion is acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fraud, willful misconduct, and indemnification are excepted from limitations. For IP infringement exceptions, the exception applies to infringement claims by third parties (covered by indemnification) but not to direct IP claims between the parties, which remain subject to the cap.', ARRAY['Fraud','willful misconduct','indemnification','excepted','limitations','IP infringement','exception','third parties','covered by indemnification','direct IP claims','between parties','subject to','cap']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Third-party IP exception only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting IP exception to third-party claims (via indemnification) while capping inter-party IP claims may be acceptable. Most IP exposure is from third parties anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exceptions to caps include fraud, willful misconduct, indemnification, confidentiality, and IP. For ProdCo specifically, the exception for representations and warranties shall be limited to representations regarding content originality, chain of title, and non-infringement.', ARRAY['Exceptions','caps','fraud','willful misconduct','indemnification','confidentiality','IP','ProdCo','exception','representations','warranties','limited','content originality','chain of title','non-infringement']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Specific rep exception categories", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting rep exception to content-related reps (originality, chain of title, non-infringement) may be acceptable as these are the core risk areas. Legal should confirm coverage is adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The parties agree to the following exceptions from the liability limitations: fraud (unlimited); willful misconduct (unlimited); gross negligence (cap at 3x fees); indemnification (unlimited); confidentiality (cap at 2x fees); IP infringement by third parties (unlimited through indemnification).', ARRAY['exceptions','liability limitations','fraud','unlimited','willful misconduct','unlimited','gross negligence','cap','3x fees','indemnification','unlimited','confidentiality','cap','2x fees','IP infringement','third parties','unlimited','indemnification']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Tiered exception structure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tiered exception structure with different caps for different categories is more complex but may be acceptable if core protections (fraud, willful misconduct, indemnification) remain unlimited."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exceptions from limitations apply to the enumerated matters. The parties acknowledge that ''fraud'' for purposes of this exception requires proof of intentional misrepresentation with knowledge of falsity and intent to induce reliance, not merely negligent misstatement.', ARRAY['Exceptions','limitations','enumerated matters','acknowledge','fraud','requires proof','intentional misrepresentation','knowledge of falsity','intent to induce reliance','not','negligent misstatement']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Fraud definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Definition of fraud requiring intentional misrepresentation is reasonable common law standard. Distinguishes from negligent misrepresentation, which remains subject to limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The limitations of liability shall apply to all claims without exception. There are no carveouts for fraud, willful misconduct, indemnification, confidentiality, or any other category of claim.', ARRAY['limitations','liability','apply','all claims','without exception','no carveouts','fraud','willful misconduct','indemnification','confidentiality','any other category']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "No exceptions to limitations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating all exceptions would cap even fraud and indemnification. Essential exceptions must be preserved for Agreement enforceability and risk allocation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from limitations apply to fraud and willful misconduct only. Indemnification obligations, confidentiality breaches, and IP claims shall remain subject to the standard cap and consequential damages exclusion.', ARRAY['Exceptions','limitations','fraud','willful misconduct only','Indemnification','confidentiality','IP claims','subject to','standard cap','consequential damages exclusion']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Limited exceptions excluding indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping indemnification defeats the entire indemnification structure. ProdCo''s indemnification must be unlimited to protect Amazon from third-party claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from the cap apply equally to both parties. If ProdCo''s indemnification is excepted from the cap, Amazon''s indemnification must also be excepted. Asymmetric exceptions are not permitted.', ARRAY['Exceptions','cap','apply equally','both parties','ProdCo''s indemnification','excepted','Amazon''s indemnification','also excepted','asymmetric exceptions','not permitted']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced symmetric exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced symmetric exceptions ignore that ProdCo''s indemnification scope is much broader than Amazon''s. Asymmetric exceptions reflect asymmetric obligations appropriately."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The fraud exception applies only to fraud that has been finally adjudicated by a court of competent jurisdiction. Alleged fraud, pending fraud claims, and fraud settlements shall remain subject to the cap until judicial determination.', ARRAY['fraud exception','applies only','fraud','finally adjudicated','court','competent jurisdiction','alleged fraud','pending','settlements','subject to','cap','until','judicial determination']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Adjudication requirement for fraud exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring final adjudication before fraud exception applies creates years of delay and caps exposure during litigation. Fraud exception must apply when fraud is alleged."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from limitations require mutual written agreement at the time the claim arises. Neither party may invoke an exception without the other party''s consent to excepting the specific claim from limitations.', ARRAY['Exceptions','limitations','require','mutual written agreement','time','claim arises','neither party','invoke','exception','without','other party''s consent','excepting','specific claim']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Consent requirement for exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Consent requirement for exceptions gives breaching party veto over having exceptions apply to its breach. Completely defeats purpose of exceptions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from the cap apply to fraud and willful misconduct. For purposes of this Agreement, ''willful misconduct'' requires proof that the party acted with specific intent to harm the other party, not merely reckless disregard for consequences.', ARRAY['Exceptions','cap','fraud','willful misconduct','Agreement','willful misconduct','requires proof','specific intent to harm','other party','not','reckless disregard']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Heightened willful misconduct standard", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring ''specific intent to harm'' for willful misconduct is heightened standard that excludes reckless conduct. Willful misconduct should include reckless disregard, not require malicious intent."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The limitations of liability set forth in this Section apply to Amazon only. ProdCo''s liability to Amazon and the Amazon Indemnitees is not limited by this Section and shall be governed by the indemnification and other provisions of this Agreement.', ARRAY['limitations of liability','apply','Amazon only','ProdCo''s liability','Amazon','Amazon Indemnitees','not limited','Section','governed by','indemnification','other provisions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Amazon-only limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "One-sided limitations applying only to Amazon is appropriate given asymmetric risk profile. ProdCo''s content obligations require unlimited exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s liability is subject to the cap and exclusions set forth herein. For the avoidance of doubt, these limitations do not apply to ProdCo, whose liability to Amazon shall be unlimited as set forth in the indemnification provisions.', ARRAY['Amazon''s liability','subject to','cap','exclusions','limitations','do not apply','ProdCo','liability','Amazon','unlimited','indemnification provisions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Clear one-sided structure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement that limitations apply to Amazon but not ProdCo. Cross-references indemnification for ProdCo''s unlimited obligations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The parties acknowledge the asymmetric risk profile of this Agreement, with ProdCo creating content and Amazon exploiting it. Accordingly, the liability limitations herein reflect this asymmetry: Amazon''s liability is limited while ProdCo''s liability for content-related matters is unlimited.', ARRAY['acknowledge','asymmetric risk profile','Agreement','ProdCo creating content','Amazon exploiting','liability limitations','reflect asymmetry','Amazon''s liability','limited','ProdCo''s liability','content-related','unlimited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Risk asymmetry acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit acknowledgment of asymmetric risk profile justifies asymmetric limitations. Reinforces enforceability of one-sided structure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Section [X] (Limitation of Liability) applies to claims by ProdCo against Amazon. Claims by Amazon against ProdCo, including indemnification claims, are not subject to Section [X] and shall be governed by the indemnification and representations/warranties provisions.', ARRAY['Limitation of Liability','applies','claims','ProdCo against Amazon','claims','Amazon against ProdCo','indemnification claims','not subject to','governed by','indemnification','representations/warranties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Direction of application", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement of limitation direction: applies to ProdCo claims against Amazon, not Amazon claims against ProdCo."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s liability is capped and Amazon excludes consequential damages as set forth herein. ProdCo waives any right to assert that similar limitations should apply to ProdCo''s obligations, acknowledging that the asymmetric structure is bargained-for and essential to the deal.', ARRAY['Amazon''s liability','capped','excludes consequential damages','ProdCo waives','right to assert','similar limitations','ProdCo''s obligations','acknowledging','asymmetric structure','bargained-for','essential']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo waiver of symmetry arguments", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo waiver of symmetry arguments prevents later challenges to one-sided structure. Reinforces that asymmetry was intentional and bargained-for."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The consequential damages exclusion is mutual and applies to both parties. The liability cap applies to Amazon only. ProdCo''s liability is subject only to the mutual consequential exclusion and is otherwise unlimited.', ARRAY['consequential damages exclusion','mutual','both parties','liability cap','Amazon only','ProdCo''s liability','subject only','mutual consequential exclusion','otherwise unlimited']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual consequential with one-sided cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual consequential exclusion with one-sided cap may be acceptable if indemnification obligations are carved out from the mutual exclusion. Legal should confirm indemnification is preserved."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party''s direct liability to the other is subject to the cap set forth herein. Notwithstanding the foregoing, ProdCo''s indemnification obligations to Amazon Indemnitees are not capped and remain unlimited regardless of any cap on direct liability.', ARRAY['each party''s','direct liability','other','subject to','cap','notwithstanding','ProdCo''s indemnification','Amazon Indemnitees','not capped','unlimited','regardless','cap','direct liability']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual direct liability cap with indemnification carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual cap on direct inter-party claims with indemnification carved out preserves core protection. Most content claims flow through indemnification anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The limitations herein apply to both parties. However, the parties acknowledge that the exceptions enumerated above apply differently: Amazon''s exceptions include only fraud and willful misconduct; ProdCo''s exceptions include all enumerated matters (indemnification, reps/warranties, confidentiality, IP, fraud, willful misconduct).', ARRAY['limitations','both parties','acknowledge','exceptions','apply differently','Amazon''s exceptions','fraud','willful misconduct','ProdCo''s exceptions','all enumerated','indemnification','reps/warranties','confidentiality','IP']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual limitations with asymmetric exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual baseline with asymmetric exceptions achieves similar result to one-sided structure. ProdCo''s broader exceptions ensure core protections remain."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The consequential damages exclusion applies mutually. The cap applies to Amazon''s liability for direct breach of Agreement. The cap does not apply to ProdCo''s liability, which is unlimited for indemnification, reps/warranties, confidentiality, and IP matters.', ARRAY['consequential damages exclusion','mutually','cap','Amazon''s liability','direct breach','Agreement','cap does not apply','ProdCo''s liability','unlimited','indemnification','reps/warranties','confidentiality','IP']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Split mutual/one-sided structure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Split structure with mutual consequential exclusion but one-sided cap may be acceptable if ProdCo''s indemnification obligations cover all consequential damages to Amazon from third-party claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Both parties agree to the limitations set forth herein. For ProdCo, the limitations apply only to claims by Amazon arising from operational breaches (delivery, format, scheduling). Content-related claims against ProdCo (through indemnification or reps/warranties) are unlimited.', ARRAY['both parties','limitations','ProdCo','limitations apply','only','claims','Amazon','operational breaches','delivery','format','scheduling','content-related claims','ProdCo','indemnification','reps/warranties','unlimited']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Operational vs. content distinction for ProdCo", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting ProdCo cap to operational matters while preserving unlimited content liability may be acceptable. Legal should confirm operational category is genuinely narrow."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The limitations of liability apply equally and symmetrically to both parties. Each party''s aggregate liability is capped at the Production Fee, and each party excludes consequential damages. No party shall have greater liability exposure than the other.', ARRAY['limitations of liability','equally','symmetrically','both parties','each party''s','aggregate liability','capped','Production Fee','excludes consequential','no party','greater liability exposure']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced symmetric limitations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced symmetric limitations would cap ProdCo''s indemnification, destroying Amazon''s protection against content claims. Symmetry ignores fundamental risk asymmetry."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon''s liability is capped, ProdCo''s liability shall be capped at the same amount. If Amazon''s cap is set at the Production Fee, ProdCo''s cap shall also equal the Production Fee. Parity in liability exposure is required.', ARRAY['Amazon''s liability','capped','ProdCo''s liability','capped','same amount','Amazon''s cap','Production Fee','ProdCo''s cap','equal','Production Fee','parity','liability exposure','required']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Mandatory parity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mandatory parity ignores that Amazon''s risks (service delivery) are different from ProdCo''s risks (content liability). ProdCo''s content obligations require unlimited exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The liability limitations are mutual. If Amazon later seeks to amend this Section to make limitations one-sided, ProdCo shall have the right to terminate this Agreement without penalty and retain all amounts paid.', ARRAY['liability limitations','mutual','Amazon seeks','amend','Section','one-sided','ProdCo','right to terminate','without penalty','retain','amounts paid']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Termination right for asymmetry", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination right triggered by asymmetric amendments prevents appropriate risk allocation changes. Combined with mutual limitations, creates unacceptable structure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties reject any asymmetric limitation structure as unconscionable. Both parties are sophisticated commercial entities entitled to equal protection. Any limitation applying to one party shall automatically apply to the other.', ARRAY['reject','asymmetric limitation','unconscionable','sophisticated commercial entities','equal protection','limitation','one party','automatically apply','other']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Unconscionability argument for symmetry", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Characterizing asymmetry as unconscionable misunderstands commercial reality. Asymmetric risk allocation is appropriate for content production agreements with different party roles."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may limit its liability only if ProdCo is entitled to equivalent limitations. If Amazon''s limitations would result in ProdCo bearing greater uncapped exposure, Amazon''s limitations shall be void and unenforceable.', ARRAY['Amazon may limit','only if','ProdCo entitled','equivalent limitations','Amazon''s limitations','result','ProdCo','greater uncapped exposure','Amazon''s limitations','void','unenforceable']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Conditional Amazon limitations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning Amazon''s limitations on ProdCo equivalence would void Amazon''s protections given necessary asymmetry. Appropriate asymmetry is feature, not bug."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Both parties agree to mutual unlimited liability. Neither party''s liability shall be capped or limited in any way. The parties accept the risks inherent in their respective obligations without limitation.', ARRAY['both parties','mutual unlimited liability','neither party''s liability','capped','limited','any way','accept risks','inherent','respective obligations','without limitation']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Mutual unlimited liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual unlimited liability eliminates Amazon''s fundamental commercial protection. Amazon requires liability cap regardless of ProdCo''s position."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement at any time, for any reason or no reason, in Amazon''s sole and absolute discretion, upon written notice to ProdCo. No advance notice period shall be required for such termination.', ARRAY['Amazon may terminate','any time','any reason','no reason','sole and absolute discretion','written notice','no advance notice','required']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Standard termination for convenience", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon termination for convenience right with no notice requirement. Essential for maintaining flexibility over production commitments. Sole discretion language is appropriate."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have the right to terminate this Agreement for convenience at any time prior to completion of principal photography by providing written notice to ProdCo. After completion of principal photography, Amazon''s termination right shall be limited to termination for cause.', ARRAY['Amazon','right to terminate','for convenience','any time','prior to','completion','principal photography','written notice','after completion','termination for cause']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Pre-principal photography convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Convenience termination limited to pre-principal photography is reasonable milestone-based approach. Preserves Amazon flexibility during development while providing production-phase certainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement at will at any stage of production. Upon such termination, Amazon shall pay ProdCo for all services rendered and costs properly incurred through the termination date, but shall have no obligation to pay any amounts not yet earned or incurred.', ARRAY['Amazon may terminate','at will','any stage','production','pay ProdCo','services rendered','costs properly incurred','termination date','no obligation','not yet earned','incurred']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Convenience termination with earned payment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Termination at will with payment for earned amounts is fair approach. No obligation for unearned amounts preserves Amazon''s ability to limit exposure upon termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for convenience by providing written notice. Amazon''s decision to terminate shall not require any justification, explanation, or prior consultation with ProdCo. ProdCo waives any right to challenge Amazon''s termination decision.', ARRAY['Amazon may terminate','for convenience','written notice','not require','justification','explanation','prior consultation','ProdCo waives','right to challenge','termination decision']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Unchallengeable termination right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit waiver of challenge rights reinforces Amazon''s sole discretion. No justification requirement is essential for convenience termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s termination for convenience right shall apply to: (a) the entire Agreement; (b) any individual season ordered; (c) any individual episode ordered; or (d) any development services. Amazon may exercise partial termination without affecting the remainder of the Agreement.', ARRAY['termination for convenience','apply to','entire Agreement','individual season','individual episode','development services','partial termination','without affecting','remainder']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Granular termination scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Granular termination options allow Amazon to reduce scope without fully terminating. Flexibility to terminate portions is important for series orders."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience. Upon such termination: (i) ProdCo shall immediately cease all work; (ii) ProdCo shall deliver all Materials in whatever state of completion; (iii) all rights shall vest in Amazon; and (iv) Amazon shall make payments as set forth in Schedule [X].', ARRAY['terminate for convenience','upon termination','immediately cease','all work','deliver','Materials','state of completion','all rights','vest','Amazon','payments','Schedule']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Termination mechanics enumerated", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear enumeration of termination consequences including work stoppage, materials delivery, rights vesting, and payment. Schedule reference provides payment specificity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for any reason. ProdCo acknowledges that the entertainment industry involves inherent uncertainty and that Amazon''s decision not to proceed with the Program shall not give rise to any claim, liability, or cause of action by ProdCo against Amazon.', ARRAY['Amazon may terminate','any reason','acknowledges','entertainment industry','inherent uncertainty','decision not to proceed','not give rise','claim','liability','cause of action']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Industry uncertainty acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment of industry uncertainty reinforces that termination is expected possibility, not breach. Waiver of claims is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience upon thirty (30) days'' prior written notice to ProdCo. During such notice period, ProdCo shall continue to perform services and Amazon shall continue to pay applicable fees.', ARRAY['Amazon may terminate','for convenience','thirty days','prior written notice','notice period','ProdCo','continue','perform services','Amazon','continue','pay','fees']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "30-day notice period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "30-day notice period is reasonable accommodation for production wind-down. Continued performance and payment during notice is appropriate quid pro quo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience. If termination occurs after commencement of principal photography, Amazon shall pay ProdCo''s documented, reasonable wind-down costs incurred within thirty (30) days following termination, up to a cap of [specified amount].', ARRAY['terminate for convenience','termination','after','commencement','principal photography','pay','documented','reasonable','wind-down costs','thirty days','following','cap','specified amount']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Capped wind-down costs", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Capped wind-down costs for post-photography termination is reasonable commercial accommodation. Cap provides predictability; documented/reasonable requirements limit exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience at any time. Amazon shall provide ProdCo with as much advance notice as is reasonably practicable under the circumstances, taking into account the stage of production and any third-party commitments of which Amazon is aware.', ARRAY['terminate for convenience','any time','provide','advance notice','reasonably practicable','circumstances','stage of production','third-party commitments','Amazon is aware']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Reasonable practicable notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Reasonably practicable'' notice is softer than fixed period and appropriate flexibility. ''Of which Amazon is aware'' qualifier is important limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate this Agreement for convenience. If Amazon exercises this right more than once across multiple projects with ProdCo within a twelve (12) month period, Amazon shall meet with ProdCo to discuss in good faith the reasons for terminations.', ARRAY['terminate','for convenience','exercises','more than once','multiple projects','twelve month period','meet with ProdCo','discuss','good faith','reasons']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Repeat termination discussion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith discussion requirement for repeated terminations is relationship-focused addition that doesn''t limit termination right itself. May be acceptable for valued partners."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience. Upon termination, Amazon shall pay: (a) the applicable kill fee set forth in Schedule [X]; plus (b) all documented third-party costs that ProdCo has irrevocably committed to and cannot mitigate, up to [specified cap].', ARRAY['terminate for convenience','upon termination','pay','kill fee','Schedule','documented','third-party costs','irrevocably committed','cannot mitigate','cap']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Kill fee plus committed costs", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Kill fee plus capped committed costs is commercial negotiation point. Business Affairs should assess whether amounts are appropriate for production scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s convenience termination right applies. If Amazon terminates during active production, Amazon shall cooperate reasonably with ProdCo''s efforts to reassign or release personnel and to cancel or assign third-party contracts, to the extent such cooperation does not impose material cost on Amazon.', ARRAY['convenience termination','applies','terminates','active production','cooperate reasonably','reassign','release personnel','cancel','assign','third-party contracts','cooperation','not impose','material cost']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Cooperation on wind-down", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reasonable cooperation with wind-down without material Amazon cost is helpful addition. Assists orderly termination without creating Amazon obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for convenience only upon ninety (90) days'' prior written notice and payment of a termination fee equal to fifty percent (50%) of the remaining Production Fee.', ARRAY['terminate','for convenience','only','ninety days','prior written notice','payment','termination fee','fifty percent','remaining Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Extended notice with penalty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "90-day notice with 50% of remaining fee as penalty substantially limits Amazon''s flexibility. Convenience termination must be unrestricted and without penalty."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience only prior to commencement of pre-production. Once pre-production has commenced, Amazon may terminate only for cause as defined herein.', ARRAY['terminate for convenience','only','prior to','commencement','pre-production','once','commenced','terminate','only','for cause']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Convenience limited to pre-pre-production", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting convenience termination to pre-pre-production is far too restrictive. Amazon needs convenience termination right through at least principal photography commencement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience. However, if Amazon terminates and subsequently produces a program substantially similar to the Program within three (3) years, ProdCo shall be entitled to the full Production Fee as if the Program had been completed.', ARRAY['terminate for convenience','however','terminates','subsequently produces','substantially similar','Program','three years','ProdCo entitled','full Production Fee','Program completed']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Similar program penalty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Penalty for producing similar content essentially prevents Amazon from terminating and developing similar projects. Fundamentally restricts Amazon''s creative development rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience only with ProdCo''s prior written consent, which consent shall not be unreasonably withheld. If ProdCo withholds consent, Amazon may terminate only upon payment of the full remaining Production Fee.', ARRAY['terminate for convenience','only','ProdCo''s prior written consent','not unreasonably withheld','ProdCo withholds consent','terminate','only','payment','full remaining Production Fee']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "ProdCo consent required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo consent for convenience termination eliminates Amazon''s discretion entirely. Amazon must have unilateral termination right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Neither party may terminate this Agreement for convenience. Termination shall be permitted only for material breach by the other party, subject to the cure provisions set forth herein.', ARRAY['neither party','terminate','for convenience','termination permitted','only','material breach','other party','subject to','cure provisions']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "No convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating convenience termination entirely removes Amazon''s fundamental right to control its slate. Amazon must retain convenience termination under all circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience. Upon such termination, ProdCo shall be entitled to the full Production Fee for all ordered episodes, regardless of the stage of production, as liquidated damages for the lost opportunity.', ARRAY['terminate for convenience','upon termination','ProdCo entitled','full Production Fee','all ordered episodes','regardless','stage of production','liquidated damages','lost opportunity']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Full fee as liquidated damages", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full Production Fee upon convenience termination makes termination economically prohibitive. Would effectively eliminate Amazon''s ability to terminate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience, but only during specified decision windows: (a) within 30 days after delivery of each script; (b) within 14 days after each production milestone; and (c) within 7 days after each cut delivery. Outside these windows, termination for convenience is not permitted.', ARRAY['terminate for convenience','only','decision windows','30 days','script','14 days','production milestone','7 days','cut delivery','outside windows','not permitted']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Window-limited convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting termination to narrow decision windows eliminates Amazon''s flexibility to respond to changing circumstances. Convenience termination must be available at any time."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement immediately upon written notice if ProdCo: (a) materially breaches any provision of this Agreement; (b) breaches any representation or warranty; (c) becomes insolvent or files for bankruptcy; (d) is the subject of any governmental investigation relating to the Program; or (e) engages in conduct that brings Amazon into disrepute.', ARRAY['Amazon may terminate','immediately','written notice','materially breaches','provision','breaches','representation','warranty','insolvent','bankruptcy','governmental investigation','conduct','brings Amazon','disrepute']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Comprehensive cause termination triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of cause termination triggers including breach, insolvency, investigation, and reputational harm. Immediate termination without cure for serious matters is appropriate."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause immediately if ProdCo breaches any material term. For non-material breaches, Amazon shall provide written notice and ProdCo shall have ten (10) business days to cure. If uncured after such period, Amazon may terminate immediately.', ARRAY['terminate for cause','immediately','breaches','material term','non-material breaches','written notice','ten business days','cure','uncured','terminate immediately']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Tiered cure based on materiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Tiered approach with immediate termination for material breach and short cure period for non-material breach is reasonable. Ten business days is adequate for minor issues."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for cause upon any breach by ProdCo of: (i) confidentiality or NPI obligations; (ii) compliance with applicable law; (iii) Amazon''s policies; (iv) representations regarding content originality or non-infringement; or (v) any obligation designated as a ''Termination Event'' in this Agreement.', ARRAY['terminate for cause','breach','confidentiality','NPI','compliance','applicable law','Amazon''s policies','representations','originality','non-infringement','Termination Event']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Specific termination event categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific high-priority breach categories that warrant immediate termination. Termination Event designation allows flexibility for deal-specific triggers."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause if any Key Person (as defined in Exhibit [X]) is no longer attached to the Program and a mutually acceptable replacement is not identified within thirty (30) days of such departure, or if ProdCo fails to deliver any deliverable by the applicable deadline and such failure continues for more than five (5) business days.', ARRAY['terminate for cause','Key Person','no longer attached','mutually acceptable replacement','thirty days','departure','fails to deliver','deliverable','deadline','failure continues','five business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Key person and delivery triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Key person departure and delivery failure are common cause triggers. Reasonable cure periods (30 days for replacement, 5 days for delivery) before termination applies."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate immediately for cause if any third party asserts a claim alleging that the Program infringes intellectual property rights, invades privacy, or constitutes defamation, regardless of the merit of such claim, if Amazon reasonably determines that the claim poses material risk.', ARRAY['terminate immediately','for cause','third party','asserts claim','alleging','Program infringes','intellectual property','invades privacy','defamation','regardless','merit','reasonably determines','material risk']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Third-party claim trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Third-party claim trigger allows Amazon to terminate when content claims arise, regardless of merit. Protects against ongoing production amid legal uncertainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Termination for cause shall be in addition to, and not in lieu of, any other remedies available to Amazon at law or in equity. Amazon''s exercise of termination rights shall not waive or limit Amazon''s right to seek damages, indemnification, or other relief.', ARRAY['termination for cause','in addition to','not in lieu of','other remedies','law','equity','exercise','termination rights','not waive','not limit','damages','indemnification','other relief']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Non-exclusive remedy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that termination doesn''t waive other remedies. Essential for preserving indemnification and damage claims alongside termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause if ProdCo or any of its principals, officers, directors, or Key Persons is publicly accused of, charged with, or convicted of any felony or crime of moral turpitude, or is the subject of credible public allegations of sexual misconduct or harassment.', ARRAY['terminate for cause','ProdCo','principals','officers','directors','Key Persons','publicly accused','charged','convicted','felony','crime of moral turpitude','credible public allegations','sexual misconduct','harassment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Morals/misconduct trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Morals clause covering criminal conduct and credible misconduct allegations. Extends to key personnel to protect against reputational harm from associated individuals."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause upon material breach. Before exercising such right, Amazon shall provide written notice specifying the breach in reasonable detail and ProdCo shall have fifteen (15) business days to cure, except that no cure period applies to breaches of confidentiality, compliance, or representations.', ARRAY['terminate for cause','material breach','before exercising','written notice','specifying','breach','reasonable detail','fifteen business days','cure','except','no cure period','confidentiality','compliance','representations']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "15-day cure with exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "15-day cure period is longer than preferred but may be acceptable for operational breaches. Exceptions for core matters (confidentiality, compliance, reps) preserve immediate termination where needed."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause. If ProdCo disputes that a termination trigger has occurred, ProdCo may provide written notice of dispute within five (5) business days, and the parties shall consult in good faith before Amazon''s termination becomes effective, provided such consultation shall not exceed ten (10) business days.', ARRAY['terminate for cause','ProdCo disputes','termination trigger','written notice','dispute','five business days','consult','good faith','before termination','effective','consultation','not exceed','ten business days']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Dispute consultation period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Short dispute consultation period (capped at 10 days) may be acceptable as it doesn''t prevent termination, just delays briefly for discussion. Timeboxed to prevent prolonged disputes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for material breach. For purposes of this Agreement, a breach shall be deemed ''material'' if it: (a) cannot be cured; (b) relates to core content, compliance, or confidentiality matters; (c) significantly impairs Amazon''s ability to exploit the Program; or (d) exposes Amazon to material liability or reputational harm.', ARRAY['terminate','material breach','breach','deemed material','cannot be cured','core content','compliance','confidentiality','significantly impairs','ability to exploit','Program','exposes Amazon','material liability','reputational harm']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Material breach definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Definition of ''material'' breach provides clarity and may reduce disputes. Categories listed are appropriately broad. Legal should confirm definition covers anticipated scenarios."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause. If the alleged cause relates to conduct of a specific individual (other than ProdCo''s principals), ProdCo shall have the opportunity to remove such individual from the production within five (5) business days in lieu of Agreement termination.', ARRAY['terminate for cause','alleged cause','relates to','conduct','specific individual','other than','principals','opportunity','remove','individual','five business days','in lieu of','Agreement termination']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Individual removal alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Removal alternative for individual misconduct (not principals) may be acceptable as it addresses the issue without full termination. Preserves Amazon''s right if removal doesn''t occur."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause upon breach. If ProdCo believes Amazon''s termination notice was issued in error or in bad faith, ProdCo may invoke the dispute resolution procedure in Section [X]; however, the Program shall remain suspended during such dispute proceedings.', ARRAY['terminate for cause','breach','ProdCo believes','termination notice','error','bad faith','invoke','dispute resolution','Section','Program','suspended','during','dispute proceedings']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Dispute resolution with suspension", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Dispute resolution option with production suspension preserves Amazon''s ability to stop work while providing ProdCo procedural recourse. Suspension is essential protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause. Amazon''s termination notice shall identify the specific breach and the provision breached. If Amazon''s notice fails to specify the breach with reasonable particularity, ProdCo may request clarification, and Amazon shall provide such clarification within three (3) business days.', ARRAY['terminate for cause','termination notice','identify','specific breach','provision breached','fails to specify','reasonable particularity','request clarification','provide','three business days']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Breach specification requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Breach specification requirement is reasonable procedural addition. Three-day clarification period is short and doesn''t materially delay termination."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause only upon ProdCo''s material breach that remains uncured for sixty (60) days after written notice. During such cure period, all payments shall continue and production shall proceed as scheduled.', ARRAY['terminate for cause','only','material breach','uncured','sixty days','written notice','cure period','payments','continue','production','proceed','scheduled']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Extended cure with continued payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "60-day cure period is far too long, and required continued payment during cure is unacceptable. Amazon must be able to terminate and suspend payments upon material breach."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause only if the breach is material and incurable, or if the breach is curable but ProdCo has failed to cure after two (2) separate written notices with thirty (30) day cure periods each.', ARRAY['terminate for cause','only','breach','material','incurable','curable','failed to cure','two separate','written notices','thirty day','cure periods','each']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Double notice requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring two separate 30-day cure periods (60+ days total) before termination is completely unacceptable. Single reasonable cure period is sufficient."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause. However, before termination becomes effective, Amazon must submit the dispute to binding arbitration and obtain an arbitral determination that ProdCo''s breach constitutes cause for termination.', ARRAY['terminate for cause','before termination','effective','submit','dispute','binding arbitration','obtain','arbitral determination','breach','constitutes','cause','termination']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Arbitration prerequisite", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring arbitration before termination is effective could take months or years. Amazon must be able to terminate immediately upon breach, with arbitration for disputed damages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause only for breaches that are both material and willful. Negligent breaches, inadvertent breaches, and breaches resulting from circumstances beyond ProdCo''s reasonable control shall not constitute cause for termination.', ARRAY['terminate for cause','only','breaches','material','willful','negligent breaches','inadvertent','circumstances','beyond','reasonable control','not constitute','cause']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Willful breach only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting cause to willful breaches excludes negligent breaches that may still be serious. Many material breaches are not willful but still warrant termination."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s right to terminate for cause shall be subject to an aggregate cap. Amazon may exercise cause termination no more than once per contract year, and each exercise shall reduce the cap by $[amount].', ARRAY['right to terminate','for cause','subject to','aggregate cap','exercise','cause termination','no more than once','per contract year','exercise','reduce','cap','amount']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Capped termination right", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping termination rights makes no sense\u2014Amazon''s right to terminate for breach cannot be limited by frequency or cost. This is fundamentally misconceived."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause. If Amazon terminates for cause but ProdCo disputes the existence of cause, and an arbitrator subsequently determines that cause did not exist, Amazon shall pay ProdCo the full remaining Production Fee plus [50%] as a termination penalty.', ARRAY['terminate for cause','ProdCo disputes','existence of cause','arbitrator','determines','cause did not exist','pay ProdCo','full remaining Production Fee','50%','termination penalty']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Penalty for disputed cause termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "150% penalty for disputed cause termination creates massive disincentive to terminate even for legitimate cause. Would chill appropriate termination decisions."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not have the right to terminate this Agreement for any reason. ProdCo''s sole remedy for any breach by Amazon shall be an action for monetary damages, subject to the limitations of liability set forth herein.', ARRAY['ProdCo','not have','right to terminate','any reason','ProdCo''s sole remedy','breach','Amazon','action','monetary damages','subject to','limitations of liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "No ProdCo termination right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo having no termination right is standard. Amazon controls whether production continues. ProdCo''s remedy is limited to monetary damages under Agreement limitations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may not terminate this Agreement. ProdCo acknowledges that specific performance and injunctive relief may be appropriate remedies for Amazon, and ProdCo waives any right to terminate as a remedy for alleged breach by Amazon.', ARRAY['ProdCo','may not terminate','acknowledges','specific performance','injunctive relief','appropriate remedies','Amazon','waives','right to terminate','remedy','alleged breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Termination waiver with equitable remedies acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit waiver of termination right as remedy. Acknowledgment of equitable remedies for Amazon reinforces that ProdCo must continue performing."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Only Amazon may terminate this Agreement. ProdCo''s exclusive remedy for any Amazon breach shall be to seek monetary damages after completion of ProdCo''s services. Under no circumstances may ProdCo cease performance, withhold Materials, or terminate this Agreement.', ARRAY['Only Amazon','may terminate','ProdCo''s exclusive remedy','Amazon breach','seek monetary damages','after completion','ProdCo''s services','no circumstances','cease performance','withhold Materials','terminate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "No performance cessation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly prohibits ProdCo from ceasing performance or withholding Materials. Damages remedy only after completion ensures production continuity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo does not have termination rights under this Agreement. If Amazon materially breaches, ProdCo''s remedy is limited to: (a) notice to Amazon of the breach; (b) a reasonable opportunity for Amazon to cure; and (c) if uncured, an action for damages subject to Agreement limitations.', ARRAY['ProdCo','does not have','termination rights','Amazon materially breaches','ProdCo''s remedy','limited','notice','breach','reasonable opportunity','cure','uncured','action for damages','Agreement limitations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Structured non-termination remedy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Provides ProdCo with notice and cure process before damages claim, but no termination right. Structured approach while preserving Amazon control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement may be terminated by Amazon only. ProdCo irrevocably waives any right it may have under applicable law or otherwise to terminate, rescind, or cancel this Agreement or to cease performance for any reason.', ARRAY['Agreement','terminated','Amazon only','ProdCo irrevocably waives','right','applicable law','otherwise','terminate','rescind','cancel','cease performance','any reason']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Comprehensive termination waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive waiver covering termination, rescission, and cancellation rights. Addresses potential statutory or common law rights that might otherwise exist."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo has no termination rights. ProdCo agrees that the Program and Amazon''s exploitation thereof are unique, and that termination by ProdCo would cause irreparable harm to Amazon for which monetary damages would be inadequate.', ARRAY['ProdCo','no termination rights','agrees','Program','Amazon''s exploitation','unique','termination','ProdCo','irreparable harm','Amazon','monetary damages','inadequate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Irreparable harm acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment of uniqueness and irreparable harm supports Amazon''s entitlement to specific performance and injunctive relief."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not terminate. Any purported termination by ProdCo shall be void and of no effect, and ProdCo shall remain obligated to perform. Amazon may treat any purported termination by ProdCo as a material breach entitling Amazon to terminate and pursue all remedies.', ARRAY['ProdCo','shall not terminate','purported termination','void','no effect','remain obligated','perform','Amazon may treat','purported termination','material breach','entitling','terminate','pursue','remedies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Void purported termination", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Makes any ProdCo termination attempt void while treating it as material breach. Strong deterrent against wrongful termination attempts."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may not terminate except in the limited circumstance where Amazon fails to pay undisputed amounts when due and such failure continues for sixty (60) days after written notice. Even then, ProdCo must first exhaust dispute resolution procedures before any termination.', ARRAY['ProdCo','may not terminate','except','limited circumstance','Amazon fails to pay','undisputed amounts','due','failure continues','sixty days','written notice','exhaust','dispute resolution','before','termination']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Payment failure exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited termination right for prolonged (60-day) undisputed payment failure with dispute resolution prerequisite may be acceptable. Protects ProdCo from non-payment while preserving Amazon control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo has no general termination right. However, if Amazon''s breach creates an imminent risk of physical harm to production personnel, ProdCo may suspend (but not terminate) production until the risk is addressed, with notice to Amazon and cooperation in remediation.', ARRAY['ProdCo','no general termination right','Amazon''s breach','imminent risk','physical harm','production personnel','suspend','not terminate','production','risk addressed','notice','cooperation','remediation']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Safety suspension only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Suspension (not termination) right for imminent physical safety risks is reasonable. Protects personnel while preserving Amazon''s ultimate control over Agreement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may not terminate. ProdCo may request that Amazon terminate the Agreement if extraordinary circumstances make continued performance impracticable, and Amazon shall consider such request in good faith, but the decision to terminate remains solely with Amazon.', ARRAY['ProdCo','may not terminate','request','Amazon terminate','Agreement','extraordinary circumstances','impracticable','Amazon','consider','good faith','decision','terminate','solely','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Termination request process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Request process for extraordinary circumstances preserves Amazon''s sole termination authority while acknowledging practical realities. Good faith consideration is minimal burden."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo has no termination right. If Amazon''s breach is material and uncured for ninety (90) days despite ProdCo''s reasonable efforts to obtain cure, ProdCo may seek a judicial declaration that the Agreement is terminated, but may not unilaterally cease performance pending such declaration.', ARRAY['ProdCo','no termination right','Amazon''s breach','material','uncured','ninety days','reasonable efforts','cure','seek','judicial declaration','terminated','not unilaterally','cease performance','pending']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Judicial declaration process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Judicial process for termination declaration (rather than unilateral right) preserves Amazon''s control and ensures dispute resolution. Continued performance requirement is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives termination rights. Notwithstanding the foregoing, ProdCo may terminate this Agreement if Amazon is adjudicated bankrupt or makes a general assignment for the benefit of creditors, provided ProdCo exercises such right within thirty (30) days of such event.', ARRAY['ProdCo waives','termination rights','notwithstanding','terminate','Amazon','adjudicated bankrupt','general assignment','benefit of creditors','exercises','within','thirty days','event']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Bankruptcy exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Bankruptcy termination exception is reasonable given fundamental change in counterparty circumstances. 30-day exercise window prevents stale claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not terminate. If ProdCo believes Amazon has materially breached, ProdCo shall provide written notice and the parties shall meet within ten (10) business days to attempt resolution. ProdCo''s sole remedy is damages; continued performance during dispute is required.', ARRAY['ProdCo','shall not terminate','believes','Amazon','materially breached','written notice','meet','ten business days','attempt resolution','sole remedy','damages','continued performance','during dispute','required']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Resolution meeting with continued performance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Resolution meeting process provides procedural mechanism for disputes without termination right. Continued performance requirement is preserved. Reasonable addition."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate this Agreement upon Amazon''s material breach that remains uncured for thirty (30) days after written notice from ProdCo.', ARRAY['ProdCo may terminate','Amazon''s material breach','uncured','thirty days','written notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "ProdCo termination for cause", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo termination right for Amazon breach reverses appropriate control structure. Amazon controls whether production continues; ProdCo''s remedy is damages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party may terminate this Agreement for material breach by the other party. ProdCo and Amazon shall have equivalent termination rights as befits their status as equal contracting parties.', ARRAY['each party','may terminate','material breach','other party','ProdCo','Amazon','equivalent termination rights','equal contracting parties']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Mutual termination rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual termination rights ignore asymmetric relationship. Amazon commissions and controls content; ProdCo provides services. ProdCo cannot have equivalent termination authority."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate this Agreement for convenience upon sixty (60) days'' written notice to Amazon. Upon such termination, ProdCo shall deliver all Materials completed through the termination date.', ARRAY['ProdCo may terminate','for convenience','sixty days','written notice','upon termination','deliver','Materials','completed','termination date']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "ProdCo convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo convenience termination right is completely unacceptable. Would allow ProdCo to abandon production for any reason, destroying Amazon''s investment and plans."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate if Amazon fails to approve any deliverable within the time periods specified herein, as such failure constitutes Amazon''s material breach of its obligation to provide timely feedback.', ARRAY['ProdCo may terminate','Amazon fails to approve','deliverable','time periods','specified','failure constitutes','Amazon''s material breach','obligation','timely feedback']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Approval delay termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination for approval delays gives ProdCo leverage to force approvals or escape Agreement. Amazon approval processes cannot be used as termination triggers."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate this Agreement if Amazon orders fewer than the minimum number of episodes specified in Section [X] for any season, as such reduction constitutes a material change to the agreed scope.', ARRAY['ProdCo may terminate','Amazon orders','fewer','minimum number','episodes','specified','Section','reduction constitutes','material change','agreed scope']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Episode reduction termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination for episode reduction restricts Amazon''s ordering discretion. Amazon''s right to determine episode orders is fundamental; ProdCo cannot terminate based on order quantity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon''s creative decisions materially deviate from ProdCo''s creative vision for the Program as set forth in the Series Bible, ProdCo may terminate this Agreement and reclaim all rights in the Program.', ARRAY['Amazon''s creative decisions','materially deviate','ProdCo''s creative vision','Program','Series Bible','ProdCo may terminate','reclaim','all rights']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Creative deviation termination with rights recapture", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Creative deviation termination with rights recapture inverts entire ownership and control structure. Amazon owns the Program and has creative control; ProdCo cannot terminate or reclaim rights."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon termination for any reason: (a) all rights granted herein shall remain vested in Amazon; (b) ProdCo shall deliver all Materials, work product, and documentation to Amazon; (c) Amazon shall own all work in progress; and (d) ProdCo shall have no right to any reversion of rights.', ARRAY['upon termination','any reason','all rights','remain vested','Amazon','deliver','Materials','work product','documentation','Amazon','own','work in progress','no right','reversion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "No reversion on termination", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement that rights remain with Amazon on any termination. No reversion under any circumstances. Essential for protecting Amazon''s investment."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Termination shall not affect: (i) Amazon''s ownership of all rights in the Program and Materials; (ii) Amazon''s right to exploit the Program in any manner; (iii) ProdCo''s indemnification obligations; (iv) any accrued rights or obligations; or (v) any provision that by its nature should survive termination.', ARRAY['termination','not affect','Amazon''s ownership','all rights','Program','Materials','right to exploit','any manner','indemnification','accrued rights','obligations','provision','nature','survive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Survival of key provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive survival provisions ensuring ownership, exploitation rights, and indemnification continue post-termination. Accrued rights preservation is standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s termination for convenience, Amazon shall pay ProdCo: (a) all amounts earned through the termination date; (b) documented costs properly incurred prior to termination; and (c) reasonable documented wind-down costs, up to [specified cap]. No other amounts shall be payable.', ARRAY['termination for convenience','pay ProdCo','amounts earned','termination date','documented costs','properly incurred','prior to termination','reasonable','wind-down costs','cap','no other amounts','payable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Convenience termination payment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear enumeration of convenience termination payments covering earned amounts and documented costs. Capped wind-down costs and ''no other amounts'' language limit exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If Amazon terminates for ProdCo''s breach, Amazon shall have no obligation to make any further payments to ProdCo, and Amazon may recover from ProdCo all damages, costs, and expenses arising from the breach, including the cost of completing the Program with a replacement production company.', ARRAY['terminates','ProdCo''s breach','no obligation','further payments','recover','ProdCo','all damages','costs','expenses','breach','cost of completing','Program','replacement production company']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Cause termination consequences", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "For-cause termination appropriately eliminates payment obligation and allows Amazon to recover all damages including replacement production costs."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Rights do not revert upon termination. ProdCo acknowledges that Amazon''s substantial investment in development, production, and marketing creates an interest that would be irreparably harmed by reversion, and ProdCo waives any reversion right that might otherwise exist.', ARRAY['Rights','not revert','termination','acknowledges','Amazon''s substantial investment','development','production','marketing','irreparably harmed','reversion','waives','reversion right']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Reversion waiver with justification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment of Amazon''s investment and waiver of reversion rights reinforces no-reversion position and provides enforcement support."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon termination, ProdCo shall within ten (10) business days: deliver all Materials in ProdCo''s possession; provide Amazon with access to all production files, accounts, and systems; assign to Amazon any third-party contracts Amazon elects to assume; and cooperate with Amazon''s transition to a replacement provider.', ARRAY['upon termination','ten business days','deliver','Materials','possession','provide','access','production files','accounts','systems','assign','Amazon','third-party contracts','elects','assume','cooperate','transition','replacement provider']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Transition cooperation requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed transition requirements ensure Amazon can continue or complete production without ProdCo. Ten-day timeline and specific deliverables create clear obligations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall have no right to any ''kill fee,'' termination payment, or other compensation upon termination except as expressly set forth in the payment schedule. Any industry custom or practice regarding termination payments is hereby waived by ProdCo.', ARRAY['no right','kill fee','termination payment','other compensation','termination','except','expressly set forth','payment schedule','industry custom','practice','termination payments','waived']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Kill fee waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit waiver of kill fees and industry customs limits ProdCo to express Agreement terms. Prevents claims based on industry practice."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon termination, all rights remain with Amazon. If Amazon does not commercially exploit the Program within five (5) years of termination, ProdCo may request in writing that Amazon discuss a potential license back of certain development materials, which Amazon may grant or deny in its sole discretion.', ARRAY['termination','all rights','remain','Amazon','does not commercially exploit','Program','five years','ProdCo','request','writing','discuss','license back','development materials','grant','deny','sole discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "License-back discussion for unexploited work", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Discussion right (not reversion right) for unexploited materials after 5 years with Amazon sole discretion may be acceptable. Doesn''t create automatic reversion or obligation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon Amazon''s convenience termination, ProdCo shall receive payments per the termination payment schedule. Additionally, if termination occurs during principal photography, Amazon shall pay the industry-standard penalty payments required to be paid to attached talent under their agreements.', ARRAY['convenience termination','ProdCo','receive payments','termination payment schedule','termination','during','principal photography','pay','industry-standard','penalty payments','attached talent','agreements']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Talent penalty passthrough", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Talent penalty passthrough for mid-photography termination is reasonable\u2014these are third-party obligations ProdCo cannot avoid. Should be verified against talent agreements."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Rights do not revert upon termination. However, ProdCo shall retain the right to receive any contingent compensation or profit participation it would have earned had the Program been completed and exploited, to the extent Amazon actually exploits the terminated Program materials.', ARRAY['Rights','not revert','termination','ProdCo','retain','right','contingent compensation','profit participation','earned','Program completed','exploited','Amazon','actually exploits','terminated','Program materials']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Contingent compensation survival", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Contingent compensation for actually-exploited terminated materials may be acceptable. Ties payment to actual exploitation rather than termination penalty."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon termination, Amazon owns all Materials. If Amazon terminates for convenience and later produces a version of the Program substantially similar to ProdCo''s creative approach, Amazon shall provide ProdCo with appropriate credit as set forth in the credit provisions, but no additional compensation.', ARRAY['termination','Amazon owns','all Materials','terminates','convenience','produces','version','Program','substantially similar','ProdCo''s creative approach','provide','appropriate credit','credit provisions','no additional compensation']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Credit for similar subsequent production", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Credit (no compensation) for subsequently-produced similar content is reasonable acknowledgment of ProdCo''s contribution without financial burden."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo acknowledges no reversion rights exist. Upon termination, ProdCo may retain copies of Materials solely for archival and portfolio purposes, subject to continued confidentiality obligations. ProdCo may reference its work on the Program in general terms for business development.', ARRAY['acknowledges','no reversion rights','termination','ProdCo','retain copies','Materials','archival','portfolio purposes','confidentiality obligations','reference','work','Program','general terms','business development']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Portfolio retention right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited portfolio retention with confidentiality and general reference rights may be acceptable for ProdCo''s business development purposes without affecting Amazon''s ownership."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No reversion upon termination. Amazon agrees that if it terminates for convenience and does not proceed with the Program, Amazon shall not assert claims against ProdCo for developing unrelated projects that may share incidental similarities with general concepts from the terminated Program.', ARRAY['no reversion','termination','Amazon','terminates','convenience','does not proceed','Program','not assert claims','ProdCo','developing','unrelated projects','incidental similarities','general concepts','terminated Program']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "No claims for unrelated similar work", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Non-assertion for incidental similarities in unrelated projects may be acceptable. Limited to general concepts, not specific Program elements. Allows ProdCo career continuity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon termination for any reason, all rights in the Program and Materials shall automatically revert to ProdCo. Amazon shall have no further rights to exploit the Program or any derivative works.', ARRAY['upon termination','any reason','all rights','Program','Materials','automatically revert','ProdCo','Amazon','no further rights','exploit','Program','derivative works']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Automatic reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Automatic reversion upon any termination completely destroys Amazon''s investment and rights. No reversion is permitted under any circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon terminates for convenience, all rights shall revert to ProdCo upon ProdCo''s repayment of 50% of amounts received from Amazon. ProdCo may then exploit the Program through any means.', ARRAY['Amazon terminates','convenience','all rights','revert','ProdCo','repayment','50%','amounts received','Amazon','exploit','Program','any means']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Buy-back reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Buy-back reversion even at 50% allows ProdCo to obtain rights Amazon invested in developing. Amazon''s rights must be absolute regardless of termination reason."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon Amazon''s termination for convenience, Amazon shall pay ProdCo the full remaining Production Fee for all ordered episodes as if production had been completed. This payment reflects ProdCo''s lost profits and opportunity costs.', ARRAY['termination for convenience','Amazon','pay ProdCo','full remaining Production Fee','all ordered episodes','production completed','lost profits','opportunity costs']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Full fee upon convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full Production Fee upon convenience termination makes termination economically prohibitive. Would eliminate Amazon''s practical ability to terminate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon terminates for cause, ProdCo disputes the cause, and an arbitrator determines the termination was wrongful, all rights shall revert to ProdCo and Amazon shall pay ProdCo the full Production Fee plus 100% as wrongful termination damages.', ARRAY['terminates for cause','ProdCo disputes','arbitrator determines','termination','wrongful','all rights','revert','ProdCo','pay','full Production Fee','100%','wrongful termination damages']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Reversion and penalty for disputed termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Reversion plus 200% payment for disputed cause termination creates massive disincentive to terminate even for legitimate cause. Rights must never revert regardless of termination circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon termination, rights remain with Amazon. However, ProdCo shall retain all underlying rights, including rights in the original literary property, format, and characters created by ProdCo, which shall revert to ProdCo free and clear.', ARRAY['upon termination','rights remain','Amazon','however','ProdCo','retain','underlying rights','original literary property','format','characters','created','ProdCo','revert','free and clear']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Underlying rights reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Reversion of underlying rights, format, and characters makes Amazon''s Program rights worthless. All rights, including underlying rights, must remain with Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon does not release the Program within two (2) years of delivery, all rights shall automatically revert to ProdCo. ProdCo may then produce the Program independently or license it to third parties.', ARRAY['Amazon','does not release','Program','two years','delivery','all rights','automatically revert','ProdCo','produce','Program','independently','license','third parties']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Time-based automatic reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Automatic time-based reversion removes Amazon''s perpetual ownership rights. Amazon''s decision whether and when to release is its sole discretion; no reversion trigger is acceptable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may suspend this Agreement and all work thereunder, including all payments, immediately upon notice to ProdCo if Amazon in good faith believes that grounds for termination may exist or if investigation of any matter relating to the Program or ProdCo is warranted.', ARRAY['Amazon may suspend','Agreement','all work','including','payments','immediately','notice','good faith believes','grounds for termination','may exist','investigation','matter','relating to','Program','ProdCo','warranted']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Broad suspension right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad suspension right for potential termination grounds or investigation needs. Payment suspension included. Amazon''s good faith belief is sufficient trigger."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may suspend production upon written notice if: (a) ProdCo may be in breach; (b) any third-party claim is asserted; (c) any governmental investigation is commenced; (d) any Key Person is subject to public allegations; or (e) Amazon determines that reputational risk exists. Payments shall be suspended during any suspension period.', ARRAY['Amazon may suspend','production','written notice','ProdCo','breach','third-party claim','asserted','governmental investigation','commenced','Key Person','public allegations','Amazon determines','reputational risk','payments','suspended','suspension period']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Enumerated suspension triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of suspension triggers including breach, claims, investigations, allegations, and reputational risk. Payment suspension protects Amazon during uncertainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'During any suspension, ProdCo shall immediately cease all work, preserve all Materials and documentation, cooperate with any Amazon investigation, and not take any action that would prejudice Amazon''s rights or position. ProdCo shall bear its own costs during suspension.', ARRAY['during suspension','ProdCo','immediately cease','all work','preserve','Materials','documentation','cooperate','Amazon investigation','not take','action','prejudice','Amazon''s rights','position','bear','own costs','suspension']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Suspension obligations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear enumeration of ProdCo''s suspension obligations including work stoppage, preservation, cooperation, and non-prejudice. ProdCo bearing own costs is appropriate given suspension trigger."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s suspension right shall be without limitation as to duration. Amazon may suspend for as long as Amazon reasonably deems necessary to investigate, evaluate, or address the matter giving rise to suspension. Amazon may terminate at any time during suspension.', ARRAY['suspension right','without limitation','duration','suspend','as long as','reasonably deems necessary','investigate','evaluate','address','matter','giving rise','suspension','terminate','any time','during suspension']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Unlimited suspension duration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Unlimited suspension duration provides Amazon maximum flexibility. Termination right during suspension ensures Amazon can exit if investigation reveals problems."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may suspend pending investigation of any credible allegation against any cast or crew member. During such suspension, Amazon may require that the subject individual be removed from the production as a condition of lifting the suspension, even if allegations are later not substantiated.', ARRAY['suspend','pending investigation','credible allegation','cast','crew member','require','subject individual','removed','production','condition','lifting suspension','allegations','not substantiated']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Personnel allegation suspension", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel allegation suspension with removal condition protects production environment and Amazon reputation. Removal requirement even without substantiation is appropriate for serious allegations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If Amazon suspends due to force majeure event (pandemic, natural disaster, civil unrest), Amazon may extend the suspension for the duration of the event plus a reasonable recovery period. Suspension payments shall be determined per Schedule [X] for force majeure events.', ARRAY['suspends','force majeure','pandemic','natural disaster','civil unrest','extend','suspension','duration','event','reasonable recovery period','suspension payments','determined','Schedule','force majeure events']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Force majeure suspension", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Force majeure suspension with recovery period addresses production disruption events. Schedule reference for payments provides specificity for these circumstances."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s suspension right is in addition to, not in lieu of, termination rights. Amazon may lift suspension and resume production, lift suspension and terminate, or continue suspension indefinitely. ProdCo shall have no right to compel Amazon to lift suspension or to resume production.', ARRAY['suspension right','in addition to','not in lieu of','termination','lift suspension','resume production','terminate','continue suspension','indefinitely','ProdCo','no right','compel','lift suspension','resume production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Suspension outcome options", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement that suspension doesn''t limit termination and that ProdCo cannot compel lifting. Multiple outcome options preserve Amazon''s flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend upon notice. If suspension continues for more than ninety (90) days, Amazon shall pay ProdCo''s documented reasonable costs of maintaining production readiness during the suspension period, up to [specified cap] per month.', ARRAY['suspend','notice','suspension continues','ninety days','Amazon','pay','documented','reasonable costs','maintaining','production readiness','suspension period','cap','per month']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Readiness payments after 90 days", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Capped readiness payments after extended suspension may be acceptable to maintain production capability. 90-day trigger and monthly cap limit exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend pending investigation. Amazon shall use reasonable efforts to complete its investigation within sixty (60) days. If investigation extends beyond sixty days, Amazon shall provide ProdCo with status updates every thirty (30) days.', ARRAY['suspend','pending investigation','reasonable efforts','complete','investigation','sixty days','extends beyond','sixty days','provide','ProdCo','status updates','thirty days']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Investigation timeline with updates", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reasonable efforts on investigation timeline and status updates are procedural accommodations that don''t limit Amazon''s suspension rights or duration."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend upon notice. During suspension, ProdCo may request in writing an explanation of the general basis for suspension. Amazon shall respond within ten (10) business days with such information as Amazon deems appropriate to share, consistent with any confidentiality or legal constraints.', ARRAY['suspend','notice','during suspension','ProdCo','request','writing','explanation','general basis','suspension','respond','ten business days','information','Amazon deems appropriate','confidentiality','legal constraints']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Explanation upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited explanation right (general basis, Amazon discretion on content) may be acceptable. Preserves confidentiality and legal constraints while providing minimal transparency."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend. If Amazon lifts suspension and elects to resume production, Amazon shall provide ProdCo with reasonable time (not less than fifteen (15) business days) to remobilize production resources before resumption of the production schedule.', ARRAY['suspend','lifts suspension','elects','resume production','provide','ProdCo','reasonable time','fifteen business days','remobilize','production resources','resumption','production schedule']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Remobilization period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Remobilization period upon resumption is practical operational need. 15 business days is reasonable minimum for production restart."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s suspension right includes the right to suspend individual elements (e.g., specific episodes, specific personnel) while permitting other production to continue. Payments shall be adjusted proportionately for partial suspensions as reasonably determined by Amazon.', ARRAY['suspension right','suspend','individual elements','specific episodes','specific personnel','permitting','other production','continue','payments','adjusted proportionately','partial suspensions','reasonably determined','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Partial suspension option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Partial suspension option provides granularity to address specific issues without full production stoppage. Proportionate payment adjustment is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If suspension results from force majeure, the parties shall cooperate in good faith to address the force majeure event and resume production as soon as practicable. Neither party shall be liable for delays caused by force majeure, but the suspension provisions shall otherwise apply.', ARRAY['suspension','force majeure','cooperate','good faith','address','force majeure event','resume production','as soon as practicable','neither party','liable','delays','caused','force majeure','suspension provisions','apply']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Force majeure cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Good faith cooperation on force majeure with no delay liability is standard. Clarification that suspension provisions otherwise apply preserves Amazon''s rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend for a maximum of thirty (30) days. If Amazon does not lift the suspension within thirty days, Amazon must either resume production or terminate. Suspension may not be extended beyond thirty days without ProdCo''s consent.', ARRAY['suspend','maximum','thirty days','does not lift','suspension','thirty days','must','resume production','terminate','may not be extended','beyond','thirty days','ProdCo''s consent']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "30-day suspension limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "30-day suspension limit with forced decision or ProdCo consent is completely inadequate. Investigations and circumstances may require extended suspension without artificial limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend with written notice. During any suspension, Amazon shall continue to make all payments to ProdCo as if production were continuing, as ProdCo must maintain its team and production infrastructure.', ARRAY['suspend','written notice','during suspension','Amazon','continue','all payments','ProdCo','production','continuing','maintain','team','production infrastructure']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Full payment during suspension", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full payment during suspension eliminates Amazon''s ability to limit exposure during uncertainty. Payment suspension is essential component of suspension right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend only for the specific grounds enumerated in this Section. Suspensions for reasons not expressly listed, or suspensions that ProdCo believes are pretextual, shall entitle ProdCo to continue production and require Amazon to continue payments.', ARRAY['suspend','only','specific grounds','enumerated','Section','suspensions','not expressly listed','ProdCo believes','pretextual','entitle','ProdCo','continue production','require','Amazon','continue payments']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Limited grounds with pretext challenge", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting suspension to enumerated grounds with pretext challenge right gives ProdCo ability to override Amazon''s suspension decision. Amazon must have broad, unchallengeable suspension right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon suspends, ProdCo may elect to terminate this Agreement upon thirty (30) days'' written notice if the suspension continues for more than sixty (60) days, and upon such termination all rights shall revert to ProdCo.', ARRAY['Amazon suspends','ProdCo','elect','terminate','thirty days','written notice','suspension continues','sixty days','termination','all rights','revert','ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "Suspension", "note": "ProdCo termination and reversion for extended suspension", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo termination right with reversion for extended suspension completely undermines Amazon''s suspension right. Would force Amazon to lift suspension or lose rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend upon notice. Any suspension exceeding fourteen (14) days shall entitle ProdCo to compensation equal to [percentage] of the Production Fee for each week of continued suspension, as liquidated damages for the disruption.', ARRAY['suspend','notice','suspension exceeding','fourteen days','entitle','ProdCo','compensation','percentage','Production Fee','each week','continued suspension','liquidated damages','disruption']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Per-week suspension penalty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Weekly suspension penalty makes extended suspension economically prohibitive. Would pressure Amazon to lift suspension before investigation is complete."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend only after providing ProdCo with detailed written grounds for suspension and giving ProdCo fifteen (15) business days to respond to such grounds. If ProdCo''s response satisfactorily addresses the grounds, Amazon may not proceed with suspension.', ARRAY['suspend','only after','detailed written grounds','suspension','giving ProdCo','fifteen business days','respond','ProdCo''s response','satisfactorily addresses','grounds','Amazon may not proceed','suspension']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Pre-suspension response period", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Pre-suspension response period with ProdCo ability to block suspension eliminates Amazon''s ability to act quickly when needed. Immediate suspension must be available."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall obtain and maintain throughout the term of this Agreement and for a period of not less than three (3) years thereafter: (a) Commercial General Liability insurance with limits of not less than $2,000,000 per occurrence and $5,000,000 aggregate; (b) Errors and Omissions insurance with limits of not less than $3,000,000 per claim and $5,000,000 aggregate; (c) Workers'' Compensation insurance as required by applicable law; and (d) Commercial Automobile Liability insurance with limits of not less than $1,000,000 combined single limit.', ARRAY['obtain','maintain','throughout term','three years thereafter','Commercial General Liability','$2,000,000 per occurrence','$5,000,000 aggregate','Errors and Omissions','$3,000,000 per claim','$5,000,000 aggregate','Workers'' Compensation','applicable law','Commercial Automobile Liability','$1,000,000 combined single limit']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Standard insurance requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive insurance requirements covering CGL, E&O, Workers'' Comp, and Auto. Limits are appropriate minimums for production activities. Three-year tail provides post-production coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain: (i) Commercial General Liability insurance covering bodily injury, property damage, personal injury, and advertising injury; (ii) Producers Errors and Omissions insurance covering claims arising from the content of the Program including infringement, defamation, and invasion of privacy; (iii) Workers'' Compensation and Employers Liability insurance; and (iv) Hired and Non-Owned Automobile Liability insurance.', ARRAY['Commercial General Liability','bodily injury','property damage','personal injury','advertising injury','Producers Errors and Omissions','claims','content','Program','infringement','defamation','invasion of privacy','Workers'' Compensation','Employers Liability','Hired and Non-Owned Automobile']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Specified coverage types", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specifies coverage types for each policy category. E&O specifically covers content-related claims. Hired/Non-Owned Auto addresses production vehicle use."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Insurance requirements include: Cast Insurance covering death, disability, or incapacity of Key Persons; Negative Film and Videotape Insurance covering loss of or damage to raw stock, exposed film, and recorded videotape; Faulty Stock, Camera, and Processing Insurance; Extra Expense Insurance; and Props, Sets, and Wardrobe Insurance.', ARRAY['Cast Insurance','death','disability','incapacity','Key Persons','Negative Film','Videotape Insurance','loss','damage','raw stock','exposed film','recorded videotape','Faulty Stock','Camera','Processing','Extra Expense','Props','Sets','Wardrobe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Production-specific coverages", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Production-specific insurance types addressing cast contingency, negative/media protection, equipment, and physical assets. Essential for comprehensive production protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall obtain Umbrella/Excess Liability insurance with limits of not less than $10,000,000 per occurrence and aggregate, providing excess coverage over the Commercial General Liability, Automobile Liability, and Employers Liability policies.', ARRAY['Umbrella','Excess Liability','$10,000,000','per occurrence','aggregate','excess coverage','Commercial General Liability','Automobile Liability','Employers Liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Umbrella coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Umbrella coverage provides additional protection above primary limits. $10M is appropriate for significant productions. Excess over multiple policy types ensures comprehensive protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All required insurance policies shall: (a) be written on an occurrence basis (except E&O which may be claims-made with retroactive date prior to commencement of services); (b) be issued by insurers with A.M. Best ratings of A- VII or better; (c) be primary and non-contributory; and (d) include a waiver of subrogation in favor of Amazon.', ARRAY['occurrence basis','except E&O','claims-made','retroactive date','prior to commencement','A.M. Best','A- VII','primary','non-contributory','waiver of subrogation','favor of Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Policy specifications", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Key policy specifications: occurrence basis for CGL, claims-made with retro date for E&O, carrier quality rating, primary/non-contributory status, and subrogation waiver. Industry-standard requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain Cyber Liability insurance with limits of not less than $1,000,000 covering data breach, network security liability, media liability, and regulatory defense and penalties, to the extent ProdCo handles personal data or confidential information in connection with the production.', ARRAY['Cyber Liability','$1,000,000','data breach','network security liability','media liability','regulatory defense','penalties','personal data','confidential information','production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Cyber liability coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cyber coverage is increasingly important for productions handling personal data. Coverage for breach, security liability, and regulatory matters addresses modern production risks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For productions involving stunts, special effects, pyrotechnics, or hazardous activities, ProdCo shall obtain additional coverage including Stunt Liability, Pyrotechnics Coverage, Aircraft/Watercraft Liability (as applicable), and increased CGL limits of not less than $5,000,000 per occurrence.', ARRAY['stunts','special effects','pyrotechnics','hazardous activities','additional coverage','Stunt Liability','Pyrotechnics Coverage','Aircraft','Watercraft Liability','increased CGL','$5,000,000 per occurrence']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Hazardous activity coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Additional coverage requirements for hazardous production activities. Increased CGL limits and specialized policies address elevated risk scenarios."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the insurance types specified herein. If any required coverage is not commercially available on reasonable terms, ProdCo shall promptly notify Amazon and the parties shall discuss alternatives. Amazon may waive or modify requirements in its reasonable discretion.', ARRAY['insurance types','specified','not commercially available','reasonable terms','promptly notify','Amazon','discuss alternatives','waive','modify','reasonable discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Commercial availability exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Commercial availability exception with Amazon waiver discretion is reasonable given occasional market constraints. Prompt notification and Amazon approval required."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Insurance limits may be satisfied through any combination of primary and umbrella/excess policies. The aggregate of primary and excess limits shall meet or exceed the required amounts. Certificates shall identify all policies contributing to required limits.', ARRAY['limits','satisfied','combination','primary','umbrella','excess policies','aggregate','meet','exceed','required amounts','certificates','identify','policies','contributing']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Combined limit satisfaction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Allowing combined primary/excess to meet limits provides flexibility without reducing coverage. Certificate identification ensures transparency."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain required coverages. For productions with budgets under $[threshold], the following reduced limits shall apply: CGL $1,000,000/$2,000,000; E&O $1,000,000/$2,000,000; Umbrella $5,000,000. Amazon may increase limits if production scope expands.', ARRAY['required coverages','productions','budgets under','threshold','reduced limits','CGL $1,000,000/$2,000,000','E&O $1,000,000/$2,000,000','Umbrella $5,000,000','increase limits','production scope expands']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Budget-based tiered limits", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tiered limits based on budget may be acceptable for smaller productions. Amazon''s right to increase limits preserves flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain E&O insurance on a claims-made basis with a retroactive date no later than the earlier of the Effective Date or commencement of development services. The policy shall be maintained for at least three (3) years following final delivery, or ProdCo shall purchase an extended reporting period (tail) of equivalent duration.', ARRAY['E&O insurance','claims-made','retroactive date','Effective Date','commencement','development services','maintained','three years','final delivery','extended reporting period','tail','equivalent duration']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Claims-made tail requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Claims-made policy with proper retro date and tail requirement ensures coverage for claims arising after production. Three-year tail is appropriate minimum."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain insurance as specified. ProdCo may self-insure the first $[amount] of any claim under CGL or Auto policies, provided ProdCo demonstrates financial capacity to cover such self-insured retention and Amazon approves the arrangement in writing.', ARRAY['insurance','specified','self-insure','first','amount','claim','CGL','Auto','financial capacity','self-insured retention','Amazon approves','writing']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Self-insured retention option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Self-insured retention with Amazon approval and financial capacity demonstration may be acceptable for established ProdCos. Maintains insurance above retention level."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Insurance requirements specified herein represent minimums. ProdCo acknowledges that Amazon''s risk management team may require increased limits or additional coverages based on specific production risks, locations, or activities, and ProdCo shall comply with such requirements.', ARRAY['requirements','minimums','Amazon''s risk management','require','increased limits','additional coverages','production risks','locations','activities','comply','requirements']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Risk-based adjustment right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s ability to require increased coverage for specific risks is appropriate. Stated minimums don''t limit Amazon''s ability to require more based on circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use commercially reasonable efforts to obtain the insurance coverages specified herein. If any coverage is unavailable or prohibitively expensive, ProdCo shall notify Amazon and proceed with production without such coverage.', ARRAY['commercially reasonable efforts','obtain','insurance coverages','unavailable','prohibitively expensive','notify Amazon','proceed','production','without','coverage']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Reasonable efforts with proceed-without option", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' standard with ability to proceed without coverage is completely unacceptable. Insurance is mandatory; Amazon cannot be exposed to uninsured production risks."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain CGL and Workers'' Compensation insurance as required by law. E&O insurance shall be optional and at ProdCo''s discretion. Amazon shall not require insurance coverages beyond those mandated by applicable law.', ARRAY['CGL','Workers'' Compensation','required by law','E&O','optional','ProdCo''s discretion','Amazon','not require','insurance','beyond','mandated','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "E&O optional with legal minimum only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "E&O is essential for content liability; making it optional is completely unacceptable. Amazon''s insurance requirements properly exceed legal minimums."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall obtain insurance with limits determined by ProdCo based on industry standards and ProdCo''s assessment of production risks. Amazon may not specify minimum limits or required coverage types.', ARRAY['insurance','limits','determined by ProdCo','industry standards','ProdCo''s assessment','production risks','Amazon may not specify','minimum limits','required coverage types']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "ProdCo-determined coverage", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-determined coverage with no Amazon minimums eliminates Amazon''s protection. Amazon must specify required coverage types and minimum limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Insurance requirements shall be shared between the parties. Amazon shall obtain and pay for E&O insurance covering the Program. ProdCo shall obtain CGL and Workers'' Compensation only.', ARRAY['insurance requirements','shared','parties','Amazon','obtain','pay for','E&O','covering','Program','ProdCo','CGL','Workers'' Compensation only']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "Split insurance responsibility", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Shifting E&O to Amazon reverses appropriate allocation. ProdCo creates content and must insure against content claims. Amazon should be additional insured, not primary insured."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain insurance. The cost of all required insurance shall be a production cost reimbursable by Amazon as a line item in the Production Budget, with no cap on insurance costs.', ARRAY['maintain insurance','cost','required insurance','production cost','reimbursable','Amazon','line item','Production Budget','no cap','insurance costs']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Uncapped insurance cost passthrough", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Uncapped insurance cost passthrough shifts all insurance cost risk to Amazon. Insurance should be within approved budget, not unlimited passthrough."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain E&O insurance with limits of $500,000 per claim and $1,000,000 aggregate. These limits reflect industry standards for independent productions and shall not be increased.', ARRAY['E&O insurance','$500,000 per claim','$1,000,000 aggregate','industry standards','independent productions','not be increased']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Inadequate E&O limits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$500K/$1M E&O limits are grossly inadequate for Amazon content. Minimum E&O should be $3M/$5M or higher depending on production scope."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All insurance policies required hereunder (except Workers'' Compensation) shall name Amazon.com, Inc. and its parents, subsidiaries, affiliates, successors, assigns, officers, directors, employees, and agents as additional insureds. Such coverage shall be primary and non-contributory with respect to any insurance or self-insurance maintained by Amazon.', ARRAY['insurance policies','except Workers'' Compensation','name','Amazon.com Inc','parents','subsidiaries','affiliates','successors','assigns','officers','directors','employees','agents','additional insureds','primary','non-contributory','insurance','self-insurance','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Standard additional insured with primary/non-contributory", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive additional insured designation covering Amazon corporate family and personnel. Primary/non-contributory status ensures Amazon''s insurance is not accessed. Workers'' Comp exception is standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall be named as additional insured using ISO form CG 20 10 (or equivalent broad form endorsement) for ongoing operations and CG 20 37 (or equivalent) for completed operations. The additional insured status shall provide coverage for Amazon''s vicarious liability arising from ProdCo''s acts or omissions.', ARRAY['additional insured','ISO form','CG 20 10','equivalent','broad form endorsement','ongoing operations','CG 20 37','completed operations','coverage','Amazon''s vicarious liability','ProdCo''s acts','omissions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Specified endorsement forms", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specifies industry-standard ISO endorsement forms for ongoing and completed operations. Vicarious liability coverage is essential for protecting Amazon from ProdCo conduct."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The additional insured coverage shall not be subject to any cross-liability exclusion, separation of insureds condition limitation, or any endorsement limiting coverage for additional insureds to the extent such limitations would reduce coverage for Amazon below that available to ProdCo as the named insured.', ARRAY['additional insured coverage','not subject to','cross-liability exclusion','separation of insureds','limitation','endorsement limiting','coverage','additional insureds','reduce coverage','Amazon','below','ProdCo','named insured']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "No coverage limitations for additional insureds", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ensures additional insured coverage is not limited by common policy exclusions. Amazon should have equivalent coverage to the named insured."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s insurers shall waive any right of subrogation against Amazon and all Amazon Indemnitees. Such waiver shall be evidenced by endorsement to the applicable policies and shall apply regardless of whether the loss arises from Amazon''s negligence.', ARRAY['insurers','waive','right of subrogation','Amazon','Amazon Indemnitees','waiver','evidenced','endorsement','applicable policies','regardless','Amazon''s negligence']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Subrogation waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Subrogation waiver prevents ProdCo''s insurers from pursuing Amazon after paying claims. Application regardless of Amazon negligence provides complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s status as additional insured shall: (a) be effective as of the earlier of the Effective Date or commencement of any services; (b) continue throughout the term and thereafter for claims arising from covered activities; and (c) extend to all Amazon-related entities that may be involved in exploitation of the Program.', ARRAY['Amazon''s status','additional insured','effective','Effective Date','commencement','services','continue','throughout term','thereafter','claims','covered activities','extend','Amazon-related entities','exploitation','Program']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Temporal and entity scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive temporal scope from pre-production through post-term claims. Extension to all Amazon-related entities ensures complete coverage of exploitation chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The primary and non-contributory requirement means that ProdCo''s insurance shall respond first without seeking contribution from any insurance maintained by Amazon. Amazon''s insurance shall be excess only and shall not be called upon to contribute until ProdCo''s insurance limits are exhausted.', ARRAY['primary','non-contributory','ProdCo''s insurance','respond first','without seeking contribution','insurance','Amazon','Amazon''s insurance','excess only','not called upon','contribute','limits','exhausted']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Primary/non-contributory explanation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear explanation of primary/non-contributory meaning prevents interpretation disputes. Amazon''s insurance is pure excess after ProdCo''s limits exhaust."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All required policies shall include an endorsement providing that Amazon shall receive not less than thirty (30) days'' prior written notice of any cancellation, non-renewal, or material change in coverage. ProdCo shall ensure that any replacement policy provides continuous coverage without gap.', ARRAY['endorsement','Amazon','receive','thirty days','prior written notice','cancellation','non-renewal','material change','coverage','replacement policy','continuous coverage','without gap']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Notice of cancellation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "30-day cancellation notice requirement is industry standard. Continuous coverage obligation ensures no gap in protection during policy transitions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall be named as additional insured. If ProdCo''s insurer will only provide ten (10) days'' notice of cancellation for non-payment of premium (which is industry standard), this shall be acceptable provided ProdCo maintains thirty (30) days'' notice for all other cancellations.', ARRAY['additional insured','insurer','ten days','notice','cancellation','non-payment','premium','industry standard','acceptable','thirty days','notice','other cancellations']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "10-day notice exception for non-payment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "10-day notice for non-payment cancellation is common insurer limitation. Acceptable if 30 days maintained for other cancellations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall be additional insured. If the policy uses a ''blanket additional insured'' endorsement that automatically covers parties required by contract, this shall satisfy the additional insured requirement provided the endorsement scope covers Amazon''s categories of additional insureds.', ARRAY['additional insured','blanket additional insured','endorsement','automatically covers','parties','required by contract','satisfy','requirement','endorsement scope','covers','Amazon''s categories']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Blanket AI endorsement acceptable", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Blanket additional insured endorsements are common and acceptable if scope is adequate. More efficient than specific endorsements for each contract."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Primary and non-contributory coverage applies. The parties acknowledge that certain excess/umbrella policies may follow the underlying insurance terms regarding contribution. Excess/umbrella following form shall be acceptable provided primary policies are non-contributory.', ARRAY['primary','non-contributory','applies','acknowledge','excess','umbrella policies','follow','underlying insurance terms','contribution','following form','acceptable','primary policies','non-contributory']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Excess following form acceptable", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Excess policies following primary terms on contribution is common structure. Acceptable if primary policies are properly non-contributory."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall be additional insured with primary and non-contributory coverage. Amazon''s additional insured status on E&O policies shall be subject to standard industry exclusions for insureds'' own independent negligence or intentional acts.', ARRAY['additional insured','primary','non-contributory','E&O','subject to','standard industry exclusions','insureds''','independent negligence','intentional acts']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "E&O standard exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "E&O exclusions for Amazon''s own negligence or intentional acts are common and generally acceptable. Coverage for ProdCo-caused claims is primary purpose."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All policies shall include Amazon as additional insured. Amazon Indemnitees beyond Amazon.com, Inc. and its direct affiliates shall be added upon Amazon''s written request, and ProdCo shall use reasonable efforts to obtain such additional coverage without material additional premium.', ARRAY['policies','include','Amazon','additional insured','Amazon Indemnitees','beyond','Amazon.com Inc','direct affiliates','added','written request','reasonable efforts','additional coverage','without material additional premium']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Extended AI upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Core Amazon entities as automatic AI with others upon request is acceptable structure. Reasonable efforts qualification and material premium exception are practical limitations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Subrogation waiver in favor of Amazon applies. Such waiver shall be obtained where available and commercially reasonable. If waiver is not available, ProdCo shall notify Amazon and the parties shall discuss allocation of any subrogation risk.', ARRAY['subrogation waiver','favor of Amazon','applies','obtained','available','commercially reasonable','not available','notify Amazon','discuss','allocation','subrogation risk']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Subrogation waiver with availability exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Subrogation waiver with commercial availability exception addresses occasional insurer limitations. Discussion of allocation provides flexibility for unusual situations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall be named as additional insured on a contributory basis. ProdCo''s insurance and Amazon''s insurance shall contribute equally to any covered claims based on respective policy limits.', ARRAY['additional insured','contributory basis','ProdCo''s insurance','Amazon''s insurance','contribute equally','covered claims','respective policy limits']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Contributory instead of non-contributory", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Contributory rather than non-contributory defeats purpose of insurance requirements. Amazon''s insurance should be accessed only after ProdCo''s is exhausted."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may be named as additional insured only if ProdCo''s insurer agrees without additional premium. If additional premium is required, Amazon may elect to pay such premium or waive the additional insured requirement.', ARRAY['additional insured','only if','insurer agrees','without additional premium','additional premium required','Amazon','elect','pay','premium','waive','additional insured requirement']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "AI contingent on no premium", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning additional insured status on no additional premium effectively makes it optional. Additional insured is mandatory requirement regardless of premium impact."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall be additional insured on CGL only. E&O coverage shall insure ProdCo only; Amazon shall be covered by its own E&O policy for any claims arising from the Program.', ARRAY['additional insured','CGL only','E&O','insure','ProdCo only','Amazon','covered','own E&O','claims','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "AI on CGL only, not E&O", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding Amazon from E&O additional insured status removes coverage for the most significant claims (content liability). Amazon must be AI on all required policies except Workers'' Comp."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s additional insured coverage shall be secondary to any insurance maintained by Amazon. If Amazon has available insurance, that coverage shall respond first before ProdCo''s policies are accessed.', ARRAY['additional insured coverage','secondary','insurance','Amazon','Amazon has available insurance','coverage','respond first','ProdCo''s policies','accessed']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "Secondary rather than primary", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Secondary coverage inverts proper insurance structure. ProdCo''s insurance must be primary; Amazon''s insurance should be pure excess."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain additional insured status for Amazon subject to standard policy exclusions. Amazon''s additional insured coverage shall be limited to claims directly caused by ProdCo''s sole negligence and shall not cover claims arising from Amazon''s comparative fault.', ARRAY['additional insured status','Amazon','standard policy exclusions','limited','claims','directly caused','ProdCo''s sole negligence','not cover','claims','Amazon''s comparative fault']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Sole negligence limitation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Sole negligence limitation excludes claims where Amazon has any fault. Vicarious liability claims typically involve some Amazon involvement; coverage must apply to all claims arising from ProdCo''s conduct."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may be additional insured. ProdCo''s insurers reserve the right to subrogate against Amazon for any claims arising from Amazon''s negligence, direction, or instructions provided to ProdCo during production.', ARRAY['additional insured','insurers','reserve','right','subrogate','Amazon','claims','Amazon''s negligence','direction','instructions','provided','ProdCo','production']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Retained subrogation rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Retained subrogation rights defeat purpose of additional insured status. Amazon would face claims from ProdCo''s insurers after they pay claims. Subrogation must be waived."}'::jsonb)
